CREATE TABLE fashion_passes(id UUID PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('SEASON','MEMBERSHIP')),starts_at TIMESTAMPTZ(3) NOT NULL,ends_at TIMESTAMPTZ(3) NOT NULL,price_diamonds BIGINT NOT NULL CHECK(price_diamonds BETWEEN 0 AND 1000000),tiers JSONB NOT NULL CHECK(jsonb_typeof(tiers)='array'),active BOOLEAN NOT NULL DEFAULT FALSE,version INT NOT NULL DEFAULT 1,CHECK(starts_at<ends_at));
